// packages/database/src/db/schema/approval-request.ts
// Drizzle table: approvalRequest (generated by scripts/split-schema.ts)

import { createId } from '@paralleldrive/cuid2'
import type { ResourcePermission, Rung } from '../../enums'
import {
  type AnyPgColumn,
  approvalKind,
  approvalStatus,
  check,
  index,
  jsonb,
  pgTable,
  sql,
  text,
  timestamp,
  uniqueIndex,
} from './_shared'
import { Organization } from './organization'
import { User } from './user'
import { Workflow } from './workflow'
import { WorkflowRun } from './workflow-run'

/**
 * Drizzle table for approvalRequest — the shared approval spine for TWO kinds
 * (plan 28 §1):
 *
 * - `kind: 'workflow'` — the human-confirmation node. Carries
 *   `workflowId`/`workflowRunId`/`nodeId`/`nodeName`.
 * - `kind: 'access'` — a member asking for permission. Carries
 *   `requesterId`/`targetKind`/`entityDefinitionId`/`entityInstanceId`/`area` and
 *   the requested/granted level (+ the instance rung, carried on the
 *   historically-named `requestedLens`/`grantedLens` pair).
 *
 * The two kinds share `status`, `assigneeUsers[]`, `assigneeGroups[]`,
 * `expiresAt`, `metadata`, `ApprovalResponse` rows, the pending list and the
 * badge count. `subjectLabel` (was `workflowName`) is the denormalized display
 * string both kinds render — for a DENIED access requester it is the only way to
 * see what they asked for, since they never got access to hydrate the target.
 */
export const ApprovalRequest = pgTable(
  'ApprovalRequest',
  {
    id: text()
      .$defaultFn(() => createId())
      .primaryKey()
      .notNull(),
    organizationId: text()
      .notNull()
      .references((): AnyPgColumn => Organization.id, { onUpdate: 'cascade', onDelete: 'cascade' }),
    /** Which lane this row belongs to. Defaults to `workflow` so existing rows backfill. */
    kind: approvalKind().default('workflow').notNull(),
    // ── workflow-only columns (nullable since plan 28 §3) ──
    workflowId: text().references((): AnyPgColumn => Workflow.id, {
      onUpdate: 'cascade',
      onDelete: 'restrict',
    }),
    workflowRunId: text().references((): AnyPgColumn => WorkflowRun.id, {
      onUpdate: 'cascade',
      onDelete: 'restrict',
    }),
    nodeId: text(),
    /**
     * Deliberately NOT generalized alongside `workflowName` (plan 28 §3.1): its
     * access-request counterpart would be the type noun, which is already
     * derivable from `entityDefinitionId`. Workflow-only.
     */
    nodeName: text(),
    status: approvalStatus().default('pending').notNull(),
    message: text(),
    assigneeUsers: text().array(),
    assigneeGroups: text().array(),
    /**
     * Denormalized display label, NOT NULL for both kinds (plan 28 §3.1).
     * Snapshot semantics: live wins when the reader can hydrate the subject, this
     * is the fallback and the durability guarantee (subject renamed, deleted, or
     * the reader has no access).
     */
    subjectLabel: text().notNull(),
    createdById: text()
      .notNull()
      .references((): AnyPgColumn => User.id, { onUpdate: 'cascade', onDelete: 'cascade' }),
    // ── access-only columns (all nullable) ──
    /**
     * Who is asking. Redundant with `createdById` for today's self-service flow,
     * but explicit: a future admin-filed-on-behalf-of request separates the two.
     */
    requesterId: text().references((): AnyPgColumn => User.id, {
      onUpdate: 'cascade',
      onDelete: 'cascade',
    }),
    /** `'instance' | 'area' | 'def'`. */
    targetKind: text(),
    /** instance/def kinds. For mail-sharing defs this is the entity SLUG (`thread`). */
    entityDefinitionId: text(),
    /** instance kind only. */
    entityInstanceId: text(),
    /** area kind only — an `Area` registry key. */
    area: text(),
    requestedLevel: text().$type<ResourcePermission>(),
    grantedLevel: text().$type<ResourcePermission>(),
    /**
     * The INSTANCE-lane rung asked for / written — the same {@link Rung} ladder
     * `ResourceAccess.rung` stores, in the same TypeScript-over-`text`
     * representation rather than a DB enum.
     *
     * **Both instance lanes write it, and they use different ranges** (plan
     * v3/04 §2.2):
     *
     * - the **thread** lane is always `read`. Mail has no picker (plan 42 §0.2)
     *   and `read` is the widest a thread can ever be seen at, so the value is
     *   hardcoded.
     * - the **record** lane is `read` or `edit`, derived server-side from the
     *   requester's current rung (`none → read`, `read → edit`). `admin` is
     *   deliberately unrequestable — sharing authority is delegated, not asked
     *   for — and `none` is a restriction marker, never a grant.
     *
     * ⚠ **The `Lens` in the NAME is a historical residual, kept on purpose.**
     * These columns were typed `'metadata' | 'identity' | 'read'` when only mail
     * filed instance requests; migration 0319 already rewrote the stored VALUES
     * onto the rung vocabulary (`subject`→`identity`, `full`→`read`) alongside
     * `ResourceAccess`, so widening the TypeScript type to {@link Rung} is a
     * pure type change that emits no SQL. Renaming them to `requestedRung` /
     * `grantedRung` was considered and declined — the column name is not worth a
     * migration, and every reader already goes through this doc comment. Read
     * "lens" here as "instance rung".
     *
     * ⚠ `requestedLevel`/`grantedLevel` above stay {@link ResourcePermission},
     * deliberately. They also carry AREA and DEF requests, where that axis is
     * the correct one; collapsing them needs the target-kind split, not a
     * vocabulary change. For a THREAD row the pair is still the old two-column
     * encoding (`view` + a rung) — a residual this phase does not collapse. For
     * a RECORD instance row they are left NULL: the rung is authoritative for
     * the instance lane, and populating them via `rungToPermission` would add a
     * third `Rung ↔ ResourcePermission` crossing point for a redundant column.
     */
    requestedLens: text().$type<Rung>(),
    grantedLens: text().$type<Rung>(),
    metadata: jsonb(),
    createdAt: timestamp({ precision: 3 }).defaultNow().notNull(),
    expiresAt: timestamp({ precision: 3 }),
  },
  (table) => [
    index('ApprovalRequest_createdById_idx').using('btree', table.createdById.asc().nullsLast()),
    // ── Audience lookup: GIN, because the predicate is `@>` / `&&` ──
    //
    // The pending list and the badge count match assignees with
    // `arrayContains(assigneeUsers, [userId])` and
    // `arrayOverlaps(assigneeGroups, groupIds)`. These replace two B-tree indexes
    // — `(organizationId, assigneeUsers)` and `(organizationId, assigneeGroups)` —
    // which could serve NEITHER operator: a B-tree over `text[]` indexes the array
    // as one opaque sortable value, so it answers whole-array equality and nothing
    // else. Both surfaces therefore scanned the org's whole approval history while
    // still paying the write amplification of maintaining the indexes.
    //
    // Partial on `status = 'pending'` because that is the only status either query
    // asks for, and it is a small slice of the table forever — a decided approval
    // never returns to pending. Postgres can bitmap-OR the two indexes for the
    // `OR` in the assignee predicate.
    //
    // `organizationId` is deliberately NOT a leading column: a multi-column GIN
    // over a scalar needs the `btree_gin` extension, and the array match is
    // already selective (assignee ids are org-scoped users), so the org equality
    // is a cheap recheck on a handful of heap rows.
    index('ApprovalRequest_assigneeUsers_pending_gin')
      .using('gin', table.assigneeUsers)
      .where(sql`status = 'pending'`),
    index('ApprovalRequest_assigneeGroups_pending_gin')
      .using('gin', table.assigneeGroups)
      .where(sql`status = 'pending'`),
    index('ApprovalRequest_organizationId_idx').using(
      'btree',
      table.organizationId.asc().nullsLast()
    ),
    index('ApprovalRequest_status_expiresAt_idx').using(
      'btree',
      table.status.asc().nullsLast(),
      table.expiresAt.asc().nullsLast()
    ),
    index('ApprovalRequest_workflowRunId_idx').using(
      'btree',
      table.workflowRunId.asc().nullsLast()
    ),
    // ── Dedup: ONE open access request per (org, requester, target) ──
    //
    // Deliberately THREE target-specific partial indexes rather than one index
    // over all three nullable target columns (plan 42 §2.2): PostgreSQL treats
    // NULLs as distinct in a unique index, and every target shape leaves at
    // least one of `area` / `entityDefinitionId` / `entityInstanceId` null — so
    // the single-index form deduplicates nothing.
    //
    // `requestedLevel` / `requestedLens` are deliberately NOT in the identity:
    // with them, "give me view" and "actually give me edit" are two rows rather
    // than an upgrade, and the dedup never fires for the case it exists to
    // catch. A re-request updates the existing row UPWARD and re-notifies.
    uniqueIndex('ApprovalRequest_access_area_pending_key')
      .on(table.organizationId, table.requesterId, table.area)
      .where(sql`kind = 'access' AND status = 'pending' AND "targetKind" = 'area'`),
    uniqueIndex('ApprovalRequest_access_def_pending_key')
      .on(table.organizationId, table.requesterId, table.entityDefinitionId)
      .where(sql`kind = 'access' AND status = 'pending' AND "targetKind" = 'def'`),
    uniqueIndex('ApprovalRequest_access_instance_pending_key')
      .on(table.organizationId, table.requesterId, table.entityDefinitionId, table.entityInstanceId)
      .where(sql`kind = 'access' AND status = 'pending' AND "targetKind" = 'instance'`),
    // ── Deny cooldown: the TERMINAL counterpart to the pending uniques above ──
    //
    // `findInstanceDenyCooldown` asks "did anyone deny this exact (requester,
    // target) recently?" — the same key list as the pending unique, but on
    // `status = 'denied'` and non-unique (a target may be denied repeatedly over
    // its lifetime). Without it that read had no usable index at all and fell back
    // to the org-wide `organizationId` index, fetching every historical denial in
    // the org for that requester and reducing them in JS.
    //
    // `createdAt DESC` is the trailing key so the query is an index-ordered
    // `LIMIT 1` rather than a sort. That ordering is sound because the pending
    // unique above serializes the lifecycle: a second request for one target
    // cannot be created while the first is pending, so a later-created denial was
    // necessarily decided later too.
    index('ApprovalRequest_access_instance_denied_idx')
      .on(
        table.organizationId,
        table.requesterId,
        table.entityDefinitionId,
        table.entityInstanceId,
        table.createdAt.desc()
      )
      .where(sql`kind = 'access' AND status = 'denied' AND "targetKind" = 'instance'`),
    // The workflow columns are present iff this is a workflow row.
    check(
      'ApprovalRequest_workflow_columns_check',
      sql`(${table.kind} = 'workflow') = (${table.workflowRunId} IS NOT NULL)`
    ),
    // An access row HAS a target kind and a requester, and a workflow row has
    // neither. This is what makes the three shape checks below load-bearing.
    //
    // Without it they are all evadable, because a CHECK is violated only when its
    // expression is FALSE — NULL passes. `targetKind IS NULL` makes every
    // `${table.targetKind} <> '<shape>'` comparison NULL, so an access row with a
    // null `targetKind` satisfies all three shape checks AND matches none of the
    // three partial unique indexes (each requires an equality on `targetKind`).
    // Net: dedup silently bypassed — the exact failure the shape checks were
    // added to prevent (plan 42 §2.2). `requesterId` rides along for the same
    // reason: it is in all three index key lists, and NULLs are distinct there.
    check(
      'ApprovalRequest_access_columns_check',
      sql`(${table.kind} = 'access') = (${table.targetKind} IS NOT NULL AND ${table.requesterId} IS NOT NULL)`
    ),
    // The three access target shapes, so a malformed row cannot evade the
    // corresponding partial index above by leaving the wrong column populated.
    check(
      'ApprovalRequest_access_area_shape_check',
      sql`${table.targetKind} <> 'area' OR (${table.area} IS NOT NULL AND ${table.entityDefinitionId} IS NULL AND ${table.entityInstanceId} IS NULL)`
    ),
    check(
      'ApprovalRequest_access_def_shape_check',
      sql`${table.targetKind} <> 'def' OR (${table.entityDefinitionId} IS NOT NULL AND ${table.entityInstanceId} IS NULL AND ${table.area} IS NULL)`
    ),
    check(
      'ApprovalRequest_access_instance_shape_check',
      sql`${table.targetKind} <> 'instance' OR (${table.entityDefinitionId} IS NOT NULL AND ${table.entityInstanceId} IS NOT NULL AND ${table.area} IS NULL)`
    ),
  ]
)

export type ApprovalRequestEntity = typeof ApprovalRequest.$inferSelect
export type CreateApprovalRequestInput = typeof ApprovalRequest.$inferInsert
export type UpdateApprovalRequestInput = Partial<CreateApprovalRequestInput>
